from fractions import Fraction

def pi_str(c):
    # A multiple of pi, written the way you'd write it by hand
    if c == 1:
        return "π"
    if c.denominator == 1:
        return f"{c}π"
    return f"({c})π"

def whole_root(n, power):
    r = 0
    while r ** power < n:
        r = r + 1
    return r

k = int(input())
for i in range(k):
    kind = input()
    value = int(input())
    if kind == "hemisphere":
        r = Fraction(value)
        v = Fraction(4, 3) * r ** 3 / 2
        s = 4 * r ** 2 / 2 + r ** 2
        print(f"hemisphere V = {pi_str(v)}, S = {pi_str(s)}")
    else:
        if kind == "radius":
            r = Fraction(value)
        elif kind == "diameter":
            r = Fraction(value, 2)
        elif kind == "surface":
            r = Fraction(whole_root(Fraction(value, 4), 2))
        else:
            r = Fraction(whole_root(Fraction(3 * value, 4), 3))
        v = Fraction(4, 3) * r ** 3
        s = 4 * r ** 2
        print(f"r = {r}, V = {pi_str(v)}, S = {pi_str(s)}")

from fractions import Fraction

def whole_root(n, power):
    r = 0
    while r ** power < n:
        r = r + 1
    return r

n = int(input())
for i in range(n):
    kind = input()
    old = int(input())
    new = int(input())
    ratio = Fraction(new, old)
    if kind == "length":
        k = ratio
    elif kind == "area":
        k = Fraction(whole_root(ratio.numerator, 2), whole_root(ratio.denominator, 2))
    else:
        k = Fraction(whole_root(ratio.numerator, 3), whole_root(ratio.denominator, 3))
    print(f"k = {k}, areas × {k ** 2}, volumes × {k ** 3}")
